import numpy as np

def pso_basic(fitness_func, dim, bounds, num_particles=20, iterations=50, w=0.7, c1=1.5, c2=1.5):
    """
    Basic PSO (Lab 3 version) - Simple 1D/2D optimization
    
    Parameters:
        fitness_func: Function to minimize
        dim: Problem dimension
        bounds: Tuple (lower, upper)
        num_particles: Number of particles
        iterations: Number of iterations
        w: Inertia weight
        c1, c2: Cognitive and social coefficients
    
    Returns:
        best_position, best_value, convergence_history
    """
    lower, upper = bounds
    
    positions = np.random.uniform(lower, upper, (num_particles, dim))
    velocities = np.random.uniform(-1, 1, (num_particles, dim))
    pbest_positions = positions.copy()
    pbest_values = np.array([fitness_func(p) for p in positions])
    gbest_idx = np.argmin(pbest_values)
    gbest_position = pbest_positions[gbest_idx].copy()
    convergence = []
    
    for iteration in range(iterations):
        r1 = np.random.rand(num_particles, dim)
        r2 = np.random.rand(num_particles, dim)
        
        velocities = (w * velocities + 
                     c1 * r1 * (pbest_positions - positions) +
                     c2 * r2 * (gbest_position - positions))
        
        positions = positions + velocities
        positions = np.clip(positions, lower, upper)
        
        current_values = np.array([fitness_func(p) for p in positions])
        
        for j in range(num_particles):
            if current_values[j] < pbest_values[j]:
                pbest_values[j] = current_values[j]
                pbest_positions[j] = positions[j].copy()
        
        gbest_idx = np.argmin(pbest_values)
        gbest_position = pbest_positions[gbest_idx].copy()
        convergence.append(pbest_values[gbest_idx])
    
    return gbest_position, pbest_values[gbest_idx], convergence


def pso_adaptive(fitness_func, dim, bounds, num_particles=30, iterations=100, c1=1.5, c2=1.5):
    """
    Adaptive PSO (Lab 4 version) - Adaptive inertia weight
    
    Parameters:
        fitness_func: Function to minimize
        dim: Problem dimension
        bounds: Tuple (lower, upper)
        num_particles: Number of particles
        iterations: Number of iterations
        c1, c2: Cognitive and social coefficients
    
    Returns:
        best_position, best_value, convergence_history
    """
    lower, upper = bounds
    w_max = 0.9
    w_min = 0.4
    
    positions = np.random.uniform(lower, upper, (num_particles, dim))
    velocities = np.random.uniform(-1, 1, (num_particles, dim))
    pbest_positions = positions.copy()
    pbest_values = np.array([fitness_func(p) for p in positions])
    gbest_idx = np.argmin(pbest_values)
    gbest_position = pbest_positions[gbest_idx].copy()
    convergence = []
    
    v_max = 0.2 * (upper - lower)
    
    for iteration in range(iterations):
        w = w_max - (w_max - w_min) * (iteration / iterations)
        
        r1 = np.random.rand(num_particles, dim)
        r2 = np.random.rand(num_particles, dim)
        
        velocities = (w * velocities + 
                     c1 * r1 * (pbest_positions - positions) +
                     c2 * r2 * (gbest_position - positions))
        
        velocities = np.clip(velocities, -v_max, v_max)
        
        positions = positions + velocities
        positions = np.clip(positions, lower, upper)
        
        current_values = np.array([fitness_func(p) for p in positions])
        
        for j in range(num_particles):
            if current_values[j] < pbest_values[j]:
                pbest_values[j] = current_values[j]
                pbest_positions[j] = positions[j].copy()
        
        gbest_idx = np.argmin(pbest_values)
        gbest_position = pbest_positions[gbest_idx].copy()
        convergence.append(pbest_values[gbest_idx])
    
    return gbest_position, pbest_values[gbest_idx], convergence


class PSO:
    """Modular PSO class (Lab 6 version) with configurable boundary handling"""
    
    def __init__(self, fitness_func, dim, bounds, num_particles=30, iterations=100, w=0.7, c1=1.5, c2=1.5, boundary_style="clamping"):
        self.fitness_func = fitness_func
        self.dim = dim
        self.bounds = bounds
        self.num_particles = num_particles
        self.iterations = iterations
        self.w = w
        self.c1 = c1
        self.c2 = c2
        self.boundary_style = boundary_style
        self.convergence = []
        self.gbest_position = None
        self.gbest_value = float('inf')
    
    def initialize(self):
        lower, upper = self.bounds
        self.positions = np.random.uniform(lower, upper, (self.num_particles, self.dim))
        self.velocities = np.random.uniform(-1, 1, (self.num_particles, self.dim))
        self.pbest_positions = self.positions.copy()
        self.pbest_values = np.array([self.fitness_func(p) for p in self.positions])
        gbest_idx = np.argmin(self.pbest_values)
        self.gbest_position = self.pbest_positions[gbest_idx].copy()
        self.gbest_value = self.pbest_values[gbest_idx]
    
    def optimize(self):
        self.initialize()
        lower, upper = self.bounds
        v_max = 0.2 * (upper - lower)
        
        for i in range(self.iterations):
            r1 = np.random.rand(self.num_particles, self.dim)
            r2 = np.random.rand(self.num_particles, self.dim)
            
            self.velocities = (self.w * self.velocities +
                               self.c1 * r1 * (self.pbest_positions - self.positions) +
                               self.c2 * r2 * (self.gbest_position - self.positions))
            
            self.velocities = np.clip(self.velocities, -v_max, v_max)
            self.positions = self.positions + self.velocities
            self.positions = np.clip(self.positions, lower, upper)
            
            current_values = np.array([self.fitness_func(p) for p in self.positions])
            
            for j in range(self.num_particles):
                if current_values[j] < self.pbest_values[j]:
                    self.pbest_values[j] = current_values[j]
                    self.pbest_positions[j] = self.positions[j].copy()
            
            gbest_idx = np.argmin(self.pbest_values)
            if self.pbest_values[gbest_idx] < self.gbest_value:
                self.gbest_value = self.pbest_values[gbest_idx]
                self.gbest_position = self.pbest_positions[gbest_idx].copy()
            
            self.convergence.append(self.gbest_value)
        
        return self.gbest_position, self.gbest_value, self.convergence
    
    def show(self):
        """Display source code"""
        import inspect
        source = inspect.getsource(self.__class__)
        output = "\n" + "=" * 80 + "\nSOURCE CODE: PSO class\n" + "=" * 80 + "\n" + source + "=" * 80 + "\n"
        print(output)
        return source
